const AUSBILDUNG_GRUPPEN = [2];
const AUSBILDUNG_ABSENDER = 'Daniela Saxer';
// Ausbildung unterschreibt mit Namen, alle anderen Gruppen mit dem Vereinsnamen.
const signatur = AUSBILDUNG_GRUPPEN.includes(ticket.group_id)
  ? SIGNATUR.replace('DLRG OG Andernach e.V.', AUSBILDUNG_ABSENDER)
  : SIGNATUR;
const GRUSS_ZEILE = /^\s*(mit freundlichen|freundliche|viele|beste|herzliche|liebe|sportliche|schöne|schone)\s+gr(ü|ue|u)(ß|ss)(e|en)\s*[,.!]?\s*$/i;

// Schneidet eine vom Modell geschriebene Grußformel samt bereits angehängter Signatur ab.
function ohneGruss(reply) {
  const zeilen = reply.split('\n');
  const stop = Math.max(zeilen.length - 40, 0);
  for (let i = zeilen.length - 1; i >= stop; i -= 1) {
    if (GRUSS_ZEILE.test(zeilen[i])) return zeilen.slice(0, i).join('\n').trimEnd();
  }
  return reply;
}

const hinweise = [];
const rohText = ohneGruss(String(parsed.reply || '').trim())
  .replace(/[ \t]*\[INTERN:\s*([^\]]*)\]/g, (_, hinweis) => {
    hinweise.push(hinweis.trim());
    return '';
  })
  .replace(/[ \t]+$/gm, '')
  .replace(/(https?:\/\/\S+) ([.,;:!?])/g, '$1$2')
  .replace(/([^.])\.\.(?!\.)/g, '$1.')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Sorgt für Leerzeilen an sinnvollen Stellen, auch wenn das Modell sie weglässt:
// nach der Anrede und nach einem einleitenden Dank-Satz.
const ANREDE_ZEILE = /^\s*(guten (tag|morgen|abend)|hallo|liebe[rn]?|sehr geehrte[rn]?|hi)\b[^\n]*[,!]\s*$/i;
const DANK_ZEILE = /^\s*(vielen dank|herzlichen dank|danke)\b[^\n]*[.!]\s*$/i;
function absaetzeSetzen(t) {
  const zeilen = t.replace(/\r\n?/g, '\n').split('\n');
  const aus = [];
  let anredeGesehen = false;
  let dankGesehen = false;
  zeilen.forEach((zeile, i) => {
    aus.push(zeile);
    const naechste = zeilen[i + 1];
    if (naechste === undefined || !naechste.trim() || !zeile.trim()) return;
    if (!anredeGesehen && ANREDE_ZEILE.test(zeile)) {
      anredeGesehen = true;
      aus.push('');
    } else if (!dankGesehen && DANK_ZEILE.test(zeile)) {
      dankGesehen = true;
      aus.push('');
    }
  });
  return aus.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
const text = absaetzeSetzen(rohText);

// [KURSLINK: ...] bleibt im Text stehen und wird im Node "Kurslinks in Entwurf einfügen" durch den Link ersetzt.
const kurslinkHinweise = Array.from(text.matchAll(/\[KURSLINK:\s*([^\]]*)\]/g)).map((m) => m[1].trim());
// Mailtext samt Verlauf, damit der Kurs über einen darin genannten Kurscode eindeutig bestimmt werden kann.
let kurslinkKontext = '';
if (kurslinkHinweise.length > 0) {
  try {
    const nutzlast = JSON.parse(Buffer.from(eingabe.payloadB64, 'base64').toString('utf8'));
    kurslinkKontext = [nutzlast.mail.subject, String(nutzlast.mail.text).slice(0, 6000), ...nutzlast.history.slice(-3).map((h) => String(h.text).slice(0, 3000))].join('\n');
  } catch (err) {
    kurslinkKontext = '';
  }
}
const entwurf = text + '\n\n' + signatur;

const escapeHtml = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const alsAbsaetze = (t) => t
  .replace(/\r\n?/g, '\n')
  .split(/\n{2,}/)
  .map((absatz) => '<p>' + escapeHtml(absatz)
    .replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?])/g, '<a href="$1">$1</a>')
    .replace(/\n/g, '<br>') + '</p>')
  .join('');
// Signatur: jede Zeile bleibt eine eigene Zeile (leere Zeile = Abstand), wie sie auch Zammads Editor erzeugt.
const alsZeilen = (t) => t
  .replace(/\r\n?/g, '\n')
  .split('\n')
  .map((zeile) => (zeile.trim()
    ? '<div>' + escapeHtml(zeile).replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?])/g, '<a href="$1">$1</a>') + '</div>'
    : '<div><br></div>'))
  .join('');
const abstand = '<p><br></p><p><br></p>';
const entwurfHtml = alsAbsaetze(text) + abstand + alsZeilen(signatur);
const notizHtml = entwurfHtml;
const hinweiseHtml = hinweise.length
  ? '<p><b>Interne Hinweise zum KI-Entwurf</b></p><ul>' + hinweise.map((h) => '<li>' + escapeHtml(h) + '</li>').join('') + '</ul>'
  : '';

return { json: { ticket, modus: eingabe.modus, replyTo: eingabe.replyTo, messageId: eingabe.messageId, entwurf, entwurfHtml, notizHtml, hinweise, hinweiseHtml, kurslinkHinweise, kurslinkHinweiseB64: Buffer.from(JSON.stringify({ hints: kurslinkHinweise, context: kurslinkKontext })).toString('base64'), warnings: parsed.warnings, stats: parsed.stats } };

const basis = $('Antwortentwurf extrahieren').item.json;
const escapeHtml = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const KURSLINK_TAG = /\[KURSLINK:\s*([^\]]*)\]/g;

let parsed = null;
if (basis.kurslinkHinweise.length > 0) {
  try {
    parsed = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
  } catch (err) {
    parsed = null;
  }
}

const auditZeilen = [];
const platzhalter = (text) => {
  const t = `[BITTE PRÜFEN: ${text}]`;
  return { html: escapeHtml(t), plain: t };
};
// Entscheidung trifft cli.js kurslink (status link | ignoriert | unklar). Ohne gültige Antwort wird nie ein Link geraten.
const decisions = basis.kurslinkHinweise.map((hint, idx) => {
  const result = parsed && parsed.ok ? parsed.results[idx] : null;
  if (!result || !result.status) {
    auditZeilen.push(`Kurslink-Nachschlag fehlgeschlagen für „${escapeHtml(hint)}“`);
    return platzhalter(`Upload-Link für ${hint}`);
  }
  if (result.status === 'link') {
    auditZeilen.push(`Kurslink automatisch eingefügt: ${escapeHtml(result.entry.kursart)} ${escapeHtml(result.entry.code)} (${escapeHtml(result.grund)})`);
    const link = escapeHtml(result.entry.url);
    return { html: `<a href="${link}">${link}</a>`, plain: result.entry.url };
  }
  if (result.status === 'ignoriert') {
    auditZeilen.push(`Kurslink nicht eingefügt: ${escapeHtml(result.grund)} – Links gibt es automatisch erst ab 2027`);
    return platzhalter(`Upload-Link für ${result.kursart || hint} von Hand einfügen (${result.grund})`);
  }
  auditZeilen.push(`Kurslink nicht eindeutig: ${escapeHtml(result.kursart || hint)} – ${escapeHtml(result.grund)}`);
  return platzhalter(`Upload-Link für ${result.kursart || hint}: Kurs nicht eindeutig`);
});

function einfuegen(text, isHtml) {
  if (!decisions.length) return text;
  let i = 0;
  return text.replace(KURSLINK_TAG, () => {
    const d = decisions[i];
    i += 1;
    return isHtml ? d.html : d.plain;
  });
}

const entwurf = einfuegen(basis.entwurf, false);
const entwurfHtml = einfuegen(basis.entwurfHtml, true);
const notizHtml = einfuegen(basis.notizHtml, true);
const hinweiseHtml = basis.hinweiseHtml + (auditZeilen.length
  ? '<p><b>Kurslink-Automatik</b></p><ul>' + auditZeilen.map((z) => '<li>' + z + '</li>').join('') + '</ul>'
  : '');

return { json: { ...basis, entwurf, entwurfHtml, notizHtml, hinweiseHtml } };
